import re
from datetime import datetime

def kind(v):
    if v.lower() in ('true', 'false'):
        return 'boolean'
    if re.fullmatch(r'-?\d+', v):
        return 'integer'
    if re.fullmatch(r'-?\d+\.\d+', v):
        return 'decimal'
    if re.fullmatch(r'\d{4}-\d{2}-\d{2}', v):
        try:
            datetime.strptime(v, '%Y-%m-%d')
            return 'date'
        except ValueError:
            pass
    return 'text'

n = int(input())
for _ in range(n):
    v = input()
    print(f'{v}: {kind(v)}')

