n = int(input())
total, count = {}, {}
for _ in range(n):
    region, amount = input().split()
    amount = float(amount)
    total[region] = total.get(region, 0.0) + amount
    count[region] = count.get(region, 0) + 1
for region in sorted(total):
    print(f'{region} {count[region]} {total[region]:.2f} {total[region] / count[region]:.2f}')
print(f'TOTAL {n} {sum(total.values()):.2f}')
